// Puzzle: a pane of tile puzzles made from Obol's shades art, opened while
// your agents work. Terminal and desktop draw the board as a stack of
// `Client` bands with keys and mouse (./board.tsx); the other surfaces,
// which have no `Client`, play the same puzzle with buttons. The puzzle in
// play lives in session state, so every band and button draws the same one.
import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { Puzzle } from '../types'
import type { BandProps } from './board'
import { act, artOf, asPuzzle, bandRows, drawBoard, isSolved, layout, newPuzzle, rowCount, SIZES } from './puzzle'
import type { Action, Detail } from './puzzle'

const PANE = 'puzzle'
const TITLE = 'Puzzle'
const ROWS = 34
const COLUMNS = 82
const busy = atom({ plugin: 'puzzle', key: 'busy' } as const, false)
const board = atom({ plugin: 'puzzle', key: 'game' } as const, null)

/** Saves a puzzle and counts it once, the first time it is seen whole. */
async function record($: EngineInterface, game: Puzzle) {
  await $.store.set('game', game)
  if (!isSolved(game) || (await $.store.get('counted')) === game.seed) return
  const solved = Number((await $.store.get('solved')) ?? 0) + 1
  await $.store.set('counted', game.seed)
  await $.store.set('solved', solved)
  $.ui.toast(`${artOf(game.art).title} is whole. (${solved} picture${solved === 1 ? '' : 's'} made whole)`)
  $.ui.invalidate('ui.render')
}

async function isAuto($: EngineInterface) {
  return (await $.store.get('auto')) !== false
}

/** How finely the terminal draws the picture: sextants unless set to `low`. */
async function detailOf($: EngineInterface): Promise<Detail> {
  return (await $.store.get('detail')) === 'low' ? 'low' : 'high'
}

/** The puzzle in play: this session's, else the one saved last, else a new one for the hour. */
async function current($: EngineInterface): Promise<Puzzle> {
  return (
    (await read($, board)) ??
    asPuzzle(await $.store.get('game')) ??
    newPuzzle(Math.floor((await $.clock.now()) / 3_600_000))
  )
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'puzzle',
      description: 'Open the picture puzzle (/puzzle auto on|off: open it with every prompt; /puzzle detail high|low)',
    })
    await update($, busy, () => false)
    const saved = asPuzzle(await $.store.get('game'))
    if (saved) await update($, board, g => g ?? saved)

    return next(e)
  })

  on('command.run', { command: 'puzzle' }, async ($, e) => {
    const arg = e.args.trim().toLowerCase()
    if (arg === 'auto on' || arg === 'auto off') {
      await $.store.set('auto', arg === 'auto on')
      return { text: `The puzzle will ${arg === 'auto on' ? 'now' : 'no longer'} open while your agents work.` }
    }
    if (arg === 'detail high' || arg === 'detail low') {
      await $.store.set('detail', arg.slice('detail '.length))
      $.ui.invalidate('ui.render')
      return {
        text:
          arg === 'detail high'
            ? 'The puzzle draws 2x3 pixels to a cell (sextants). If the picture shows boxes, use /puzzle detail low.'
            : 'The puzzle draws 2x2 pixels to a cell (quadrants), which every font has.',
      }
    }
    await $.ui.open({ id: PANE, title: TITLE, focus: true, rows: ROWS, columns: COLUMNS })

    return { text: 'Click a tile, then another to swap them, until the picture is whole.' }
  })

  on('prompt.submit', async ($, e, next) => {
    await update($, busy, () => true)
    if (await isAuto($)) void $.ui.open({ id: PANE, title: TITLE, rows: ROWS, columns: COLUMNS })

    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    await update($, busy, () => false)

    return next(e)
  })

  on('ui.message', { requestId: PANE }, async ($, e) => {
    const game = asPuzzle((e.data as { game?: unknown } | null)?.game)
    if (game) {
      await update($, board, () => game)
      await record($, game)
    }

    return {}
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const isBusy = await read($, busy)
    const solved = Number((await $.store.get('solved')) ?? 0)
    const game = await current($)
    const columns = e.props.bodyColumns
    const rows = Math.max(16, e.props.scroll.bodyRows)

    if (e.surface === 'terminal' || e.surface === 'desktop') {
      const { Box, Client } = $.ui.resolve(e)
      // Sextants are checked in terminal fonts only; the desktop draws quadrants.
      const detail = e.surface === 'terminal' ? await detailOf($) : 'low'
      const total = rowCount(layout(game.n, columns, rows, detail))
      const bands = []
      const band = bandRows(columns)
      for (let from = 0; from < total; from += band) {
        const to = Math.min(total, from + band)
        const props: BandProps = { game, busy: isBusy, solved, from, to, columns, rows, detail }
        bands.push(
          <Client key={`band${from / band}`} module="./board.tsx" props={props} width={columns} height={to - from} />,
        )
      }
      return <Box flexDirection="column">{bands}</Box>
    }

    const { Box, Text, Button } = $.ui.resolve(e)
    const press = (a: Action) => async () => {
      const shown = await current($)
      const next = await update($, board, g => act(g ?? shown, a))
      if (next) await record($, next)
    }
    const l = layout(game.n, columns, Math.min(rows, ROWS - 4), 'low')
    const help = 'Use the buttons, or focus the pane for hotkeys: w a s d move, e pick/swap, p peek, n next.'

    return (
      <Box flexDirection="column">
        {drawBoard(game, { Box, Text }, l, { busy: isBusy, solved, help })}
        <Box flexDirection="row">
          <Button key="up" label="↑" hotkey="w" onPress={press({ t: 'move', dx: 0, dy: -1 })} />
          <Button key="left" label="←" hotkey="a" onPress={press({ t: 'move', dx: -1, dy: 0 })} />
          <Button key="down" label="↓" hotkey="s" onPress={press({ t: 'move', dx: 0, dy: 1 })} />
          <Button key="right" label="→" hotkey="d" onPress={press({ t: 'move', dx: 1, dy: 0 })} />
          <Button
            key="pick"
            label={game.pick >= 0 ? 'Swap' : 'Pick'}
            hotkey="e"
            variant={game.pick >= 0 ? 'primary' : 'secondary'}
            onPress={press({ t: 'pick' })}
          />
          <Button key="peek" label={game.peek ? 'Hide' : 'Peek'} hotkey="p" onPress={press({ t: 'peek' })} />
        </Box>
        <Box flexDirection="row">
          {SIZES.map(n => (
            <Button key={`size${n}`} label={`${n}×${n}`} hotkey={String(n)} onPress={press({ t: 'size', n })} />
          ))}
          <Button
            key="new"
            label={game.asking ? 'Yes, next picture' : 'Next picture'}
            hotkey="n"
            variant={isSolved(game) || game.asking ? 'primary' : 'secondary'}
            onPress={press({ t: 'new' })}
          />
        </Box>
      </Box>
    )
  })
}

