// One band of the puzzle board: a `Client` surface module drawing rows
// `from` to `to` of the drawing, so the keys and the mouse reach the tiles
// directly. A picture is too many coloured cells for one `Client`'s tree,
// so the pane stacks several bands. Each keeps the puzzle in its local
// state, takes the hooks module's when it is newer (another band moved),
// and posts each change of its own, which the hooks module saves and hands
// to every band.
import type { ClientKeyEvent, ClientModule, ClientPointerEvent, ClientSurface } from 'claude-code'

import type { Puzzle } from '../types'
import { act, asPuzzle, drawRows, isSolved, layout, newPuzzle, tileAt } from './puzzle'
import type { Action, Detail, Layout } from './puzzle'

export type BandProps = {
  game: Puzzle
  busy: boolean
  solved: number
  /** The drawing's rows this band shows, `to` exclusive. */
  from: number
  to: number
  /** The whole drawing's size, which every band lays out alike. */
  columns: number
  rows: number
  detail: Detail
}
/** A tile held by the pointer: where it went down, and whether it was picked before. */
type Drag = { from: number; wasPicked: boolean }
type Local = { game: Puzzle; drag: Drag | null; from: number; columns: number; rows: number; detail: Detail }
type Surface = ClientSurface<Local>

export const HELP = 'click two tiles to swap · ←↑↓→ space · p peek · 3-6 tiles · n next · esc leave'

const MOVES: Record<string, [number, number]> = {
  up: [0, -1], down: [0, 1], left: [-1, 0], right: [1, 0],
  k: [0, -1], j: [0, 1], h: [-1, 0], l: [1, 0],
  w: [0, -1], s: [0, 1], a: [-1, 0], d: [1, 0],
}

const place = (st: Local): Layout => layout(st.game.n, st.columns, st.rows, st.detail)

function commit(surface: Surface, st: Local, game: Puzzle, rest: Partial<Local> = {}) {
  surface.setState({ ...st, ...rest, game })
  if (game !== st.game) surface.post({ game })
}

function onKey(surface: Surface, k: ClientKeyEvent) {
  const st = surface.state
  if (!st) return
  const g = st.game
  const move = MOVES[k.key]
  let a: Action | null = null
  if (move) a = { t: 'move', dx: move[0], dy: move[1] }
  else if (k.key === ' ' || k.key === 'space' || k.key === 'return' || k.key === 'x' || k.key === 'e') a = { t: 'pick' }
  else if (k.key === 'c' || k.key === 'backspace' || k.key === 'delete') a = { t: 'drop' }
  else if (k.key === 'p') a = { t: 'peek' }
  else if (/^[3-6]$/.test(k.key)) a = { t: 'size', n: Number(k.key) }
  else if (k.key === 'n' || k.key === 'N') a = { t: 'new' }
  if (a) commit(surface, st, act(g, a))
}

function onPointer(surface: Surface, p: ClientPointerEvent) {
  const st = surface.state
  if (!st) return
  const g = st.game
  // The band holds the pointer from its down to its up, rows past its own included.
  const t = tileAt(place(st), p.x, st.from + p.y)
  if (p.type === 'down' && p.button === 'left') {
    if (t < 0 || isSolved(g)) return
    if (g.pick >= 0 && g.pick !== t) {
      commit(surface, st, act(g, { t: 'swap', a: g.pick, b: t }), { drag: null })
      return
    }
    commit(surface, st, act(g, { t: 'grab', p: t }), { drag: { from: t, wasPicked: g.pick === t } })
    return
  }
  const d = st.drag
  if (!d) return
  if (p.type === 'move') {
    if (t >= 0 && t !== g.cur) commit(surface, st, act(g, { t: 'goto', p: t }))
    return
  }
  if (p.type === 'up') {
    if (t >= 0 && t !== d.from) commit(surface, st, act(g, { t: 'swap', a: d.from, b: t }), { drag: null })
    else if (t === d.from && d.wasPicked) commit(surface, st, act(g, { t: 'drop' }), { drag: null })
    else commit(surface, st, t < 0 ? act(g, { t: 'goto', p: d.from }) : g, { drag: null })
  }
}

const Band: ClientModule<BandProps, Local> = (props, surface) => {
  const given = asPuzzle(props.game) ?? newPuzzle(1)
  let st = surface.state
  if (!st) {
    st = { game: given, drag: null, from: props.from, columns: props.columns, rows: props.rows, detail: props.detail }
    surface.setState(st)
    surface.onKey(k => onKey(surface, k))
    surface.onPointer(p => onPointer(surface, p))
  } else if (
    given.rev > st.game.rev ||
    props.from !== st.from ||
    props.columns !== st.columns ||
    props.rows !== st.rows ||
    props.detail !== st.detail
  ) {
    const { from, columns, rows, detail } = props
    st = { ...st, game: given.rev > st.game.rev ? given : st.game, from, columns, rows, detail }
    surface.setState(st)
  }
  const { Box, Text } = surface.elements
  return (
    <Box flexDirection="column">
      {drawRows(st.game, Text, place(st), { busy: props.busy, solved: props.solved, help: HELP }, props.from, props.to)}
    </Box>
  )
}

export default Band

