// The puzzle itself, shared by the `Client` board (terminal, desktop) and
// the button board (every other surface). Pure functions over a `Puzzle`,
// which is plain data, and a drawing that paints the picture with half
// blocks: each cell is two pixels, the top in the foreground colour.
import type { ClientElements, RenderElement } from 'claude-code'

import type { Puzzle } from '../types'
import { ART, SIZE } from './art'
import type { Art } from './art'

export const SIZES = [3, 4, 5, 6] as const
export const DEFAULT_N = 4

const CURSOR = 0xf4d35e
const PICKED = 0x7dd3fc

export type Action =
  | { t: 'move'; dx: number; dy: number }
  | { t: 'goto'; p: number }
  /** Moves the cursor to a tile and picks it. */
  | { t: 'grab'; p: number }
  | { t: 'pick' }
  | { t: 'swap'; a: number; b: number }
  | { t: 'drop' }
  | { t: 'peek' }
  | { t: 'size'; n: number }
  | { t: 'new' }

function rng(seed: number): () => number {
  let a = seed >>> 0
  return () => {
    a = (a + 0x6d2b79f5) >>> 0
    let t = a
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

const clamp = (n: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, n))

export function artOf(id: string): Art {
  return ART.find(a => a.id === id) ?? ART[0]!
}

/** A shuffle of `count` pieces with none left in its own place. */
function shuffle(count: number, r: () => number): number[] {
  const order = Array.from({ length: count }, (_, i) => i)
  for (let i = count - 1; i > 0; i--) {
    const j = Math.floor(r() * (i + 1))
    ;[order[i], order[j]] = [order[j]!, order[i]!]
  }
  for (let p = 0; p < count; p++) {
    if (order[p] !== p) continue
    const q = (p + 1) % count
    ;[order[p], order[q]] = [order[q]!, order[p]!]
  }
  return order
}

export function newPuzzle(seed: number, n: number = DEFAULT_N, art?: string): Puzzle {
  const s = (seed >>> 0) || 1
  const r = rng(s)
  const picked = art ?? ART[Math.floor(r() * ART.length)]!.id
  return {
    v: 1,
    rev: 0,
    seed: s,
    art: picked,
    n,
    order: shuffle(n * n, r),
    cur: 0,
    pick: -1,
    moves: 0,
    peek: false,
    msg: `${artOf(picked).title}. Swap the tiles until the picture is whole.`,
  }
}

/** A saved value read back from storage, if it still has the shape of one. */
export function asPuzzle(value: unknown): Puzzle | null {
  const g = value as Puzzle | null
  return g && g.v === 1 && typeof g.rev === 'number' && Array.isArray(g.order) && g.order.length === g.n * g.n
    ? g
    : null
}

export const placed = (g: Puzzle) => g.order.filter((piece, p) => piece === p).length
export const isSolved = (g: Puzzle) => placed(g) === g.order.length

function swap(g: Puzzle, a: number, b: number): Puzzle {
  if (a === b) return { ...g, pick: -1, cur: b }
  const order = [...g.order]
  ;[order[a], order[b]] = [order[b]!, order[a]!]
  const next = { ...g, order, cur: b, pick: -1, moves: g.moves + 1 }
  const title = artOf(g.art).title
  if (isSolved(next)) {
    return { ...next, msg: `${title} is whole, in ${next.moves} moves. Press n for the next picture.` }
  }
  return { ...next, msg: `${placed(next)} of ${order.length} tiles in place.` }
}

/** The puzzle after an action, its `rev` one on when anything changed. */
export function act(g: Puzzle, a: Action): Puzzle {
  // Any action but a second `new` answers "are you sure?" with no.
  const from = g.asking && a.t !== 'new' ? { ...g, asking: false, msg: `Still on ${artOf(g.art).title}.` } : g
  const next = step(from, a)
  return next === g ? g : { ...next, rev: g.rev + 1 }
}

function step(g: Puzzle, a: Action): Puzzle {
  const solved = isSolved(g)
  const last = g.n * g.n - 1
  switch (a.t) {
    case 'move': {
      if (solved) return g
      const x = clamp((g.cur % g.n) + a.dx, 0, g.n - 1)
      const y = clamp(Math.floor(g.cur / g.n) + a.dy, 0, g.n - 1)
      return { ...g, cur: y * g.n + x, peek: false }
    }
    case 'goto':
      return solved ? g : { ...g, cur: clamp(a.p, 0, last), peek: false }
    case 'grab':
      return solved ? g : { ...g, cur: clamp(a.p, 0, last), pick: clamp(a.p, 0, last), peek: false }
    case 'pick':
      if (solved) return g
      if (g.pick < 0) return { ...g, pick: g.cur, peek: false }
      return swap({ ...g, peek: false }, g.pick, g.cur)
    case 'swap':
      return solved ? g : swap({ ...g, peek: false }, clamp(a.a, 0, last), clamp(a.b, 0, last))
    case 'drop':
      return { ...g, pick: -1, peek: false }
    case 'peek':
      return solved ? g : { ...g, peek: !g.peek }
    case 'size': {
      const next = newPuzzle(rng(g.seed ^ 0x85ebca6b)() * 4294967296, a.n, g.art)
      return { ...next, msg: `${artOf(g.art).title}, now in ${a.n}×${a.n} tiles.` }
    }
    case 'new': {
      if (!solved && !g.asking) {
        return { ...g, asking: true, msg: `Are you sure? Press n again to leave ${artOf(g.art).title} unfinished.` }
      }
      const r = rng(g.seed ^ 0x9e3779b9)
      const seed = r() * 4294967296
      let i = Math.floor(r() * ART.length)
      if (ART[i]!.id === g.art) i = (i + 1) % ART.length
      return newPuzzle(seed, g.n, ART[i]!.id)
    }
  }
}

// --- pictures --------------------------------------------------------------

function decode(b64: string): Uint8Array {
  const abc = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
  const clean = b64.replace(/=+$/, '')
  const out = new Uint8Array(Math.floor((clean.length * 3) / 4))
  let bits = 0
  let acc = 0
  let o = 0
  for (const ch of clean) {
    acc = (acc << 6) | abc.indexOf(ch)
    bits += 6
    if (bits >= 8) {
      bits -= 8
      out[o++] = (acc >> bits) & 0xff
    }
  }
  return out
}

const scaled = new Map<string, number[]>()

/**
 * The picture `id` at `w` x `h` pixels, each 0xRRGGBB, averaged from SIZE
 * where it shrinks and repeated where it grows.
 */
export function picture(id: string, w: number, h: number): number[] {
  const key = `${id}@${w}x${h}`
  const hit = scaled.get(key)
  if (hit) return hit
  const art = artOf(id)
  const pal = decode(art.palette)
  const idx = decode(art.pixels)
  const out: number[] = new Array(w * h)
  for (let y = 0; y < h; y++) {
    const y0 = Math.floor((y * SIZE) / h)
    const y1 = Math.max(y0 + 1, Math.floor(((y + 1) * SIZE) / h))
    for (let x = 0; x < w; x++) {
      const x0 = Math.floor((x * SIZE) / w)
      const x1 = Math.max(x0 + 1, Math.floor(((x + 1) * SIZE) / w))
      let r = 0
      let g = 0
      let b = 0
      for (let sy = y0; sy < y1; sy++)
        for (let sx = x0; sx < x1; sx++) {
          const k = idx[sy * SIZE + sx]! * 3
          r += pal[k]!
          g += pal[k + 1]!
          b += pal[k + 2]!
        }
      const c = (x1 - x0) * (y1 - y0)
      out[y * w + x] = (Math.round(r / c) << 16) | (Math.round(g / c) << 8) | Math.round(b / c)
    }
  }
  if (scaled.size > 16) scaled.clear()
  scaled.set(key, out)
  return out
}

// --- layout ----------------------------------------------------------------

const HEADER = 1
/** The footer's lines, in the order they give way: the message, the agents, the help. */
const FOOTER = 3
const THUMB_GAP = 2
/** The most cells one board band draws, which keeps its tree well inside a `Client`'s bounds. */
const BAND_CELLS = 480

/** Rows per board band for a drawing `columns` wide. */
export const bandRows = (columns: number) => Math.max(1, Math.floor(BAND_CELLS / Math.max(1, columns)))

/** How finely a cell is split: `high` draws sextants (2 x 3 pixels), `low` quadrants (2 x 2), which every font has. */
export type Detail = 'high' | 'low'
/** Pixel rows per cell. */
type Sub = 2 | 3

export type Layout = {
  columns: number
  rows: number
  n: number
  /**
   * A tile in cells, `tw = 2 * th` so it is square on screen. Each cell is
   * 2 x `sub` pixels, so a tile is `2 * tw` by `sub * th` pixels.
   */
  tw: number
  th: number
  sub: Sub
  /**
   * Gap rows around and between the tile rows: 1, or 0 where dropping them
   * buys bigger tiles. A one-column gap always runs between the tile columns.
   */
  gap: 0 | 1
  /** The board in cells. */
  width: number
  height: number
  /** Where the board's top-left cell sits in the drawing. */
  left: number
  top: number
  /** The finished picture beside the board, in columns (rows are half); 0 when there is no room. */
  thumb: number
  /** How many footer lines there is room for, 1 to FOOTER. */
  footer: number
}

/** The tallest tile that fits, in rows, with or without gap rows. */
function fit(n: number, columns: number, room: number, gap: 0 | 1): number {
  for (let t = 40; t > 1; t--) {
    if (n * 2 * t + n + 1 <= columns && n * t + gap * (n + 1) <= room) return t
  }
  return 1
}

/** Below this many rows a tile is too small to make out, and the board takes the footer's and the gaps' rows. */
const ROOMY = 5

export function layout(n: number, columns: number, rows: number, detail: Detail = 'high'): Layout {
  let gap: 0 | 1 = 1
  let th = fit(n, columns, rows - HEADER - FOOTER, 1)
  if (th < ROOMY) {
    const room = rows - HEADER - 1
    const withGaps = fit(n, columns, room, 1)
    const without = fit(n, columns, room, 0)
    gap = without > withGaps ? 0 : 1
    th = gap ? withGaps : without
  }
  const tw = 2 * th
  const width = n * tw + n + 1
  const height = n * th + gap * (n + 1)
  // The picture beside the board takes what room the board leaves, at most about half its size.
  const spare = columns - width - THUMB_GAP
  let thumb = Math.min(spare, Math.floor((n * tw) / 2), 2 * (height - 2)) & ~1
  if (thumb < 12) thumb = 0
  const total = width + (thumb ? THUMB_GAP + thumb : 0)
  return {
    columns,
    rows,
    n,
    tw,
    th,
    sub: detail === 'high' ? 3 : 2,
    gap,
    width,
    height,
    left: Math.max(0, Math.floor((columns - total) / 2)),
    top: HEADER,
    thumb,
    footer: Math.max(1, Math.min(FOOTER, rows - HEADER - height)),
  }
}

/** The tile position under a cell of the drawing, or -1 off the tiles. */
export function tileAt(l: Layout, x: number, y: number): number {
  const bx = x - l.left - 1
  const by = y - l.top - l.gap
  if (bx < 0 || by < 0) return -1
  const c = Math.floor(bx / (l.tw + 1))
  const r = Math.floor(by / (l.th + l.gap))
  if (c >= l.n || r >= l.n || bx % (l.tw + 1) === l.tw || (l.gap && by % (l.th + 1) === l.th)) return -1
  return r * l.n + c
}

// --- drawing ---------------------------------------------------------------

/** One cell: a glyph, its foreground and its background (-1: the terminal's own). */
type Cell = { ch: string; fg: number; bg: number }

const BLANK: Cell = { ch: ' ', fg: -1, bg: -1 }
/** Quadrant glyphs by mask: top-left 1, top-right 2, bottom-left 4, bottom-right 8. */
const QUADS = ' ▘▝▀▖▌▞▛▗▚▐▜▄▙▟█'

/**
 * The sextant glyph for a mask of a cell's 2 x 3 pixels, bit i the i-th in
 * reading order. The two half columns are Block Elements, not sextants.
 */
function sextant(mask: number): string {
  if (mask === 0) return ' '
  if (mask === 63) return '█'
  if (mask === 21) return '▌'
  if (mask === 42) return '▐'
  return String.fromCodePoint(0x1fb00 + mask - 1 - (mask > 21 ? 1 : 0) - (mask > 42 ? 1 : 0))
}

const meanOf = (cs: number[]) =>
  [16, 8, 0].reduce((c, s) => c | (Math.round(cs.reduce((t, x) => t + ((x >> s) & 0xff), 0) / cs.length) << s), 0)

/**
 * A cell's 2 x `sub` pixels, in reading order, as one cell: the quadrant
 * (sub 2) or sextant (sub 3) glyph and pair of colours closest to them. It
 * tries every split of the pixels in two, the first pixel in the foreground.
 */
function block(px: number[], sub: Sub): Cell {
  const rgb = px.map(c => [(c >> 16) & 0xff, (c >> 8) & 0xff, c & 0xff])
  const uniform = (1 << px.length) - 1
  let best: Cell = BLANK
  let bestErr = Infinity
  for (let mask = 0; mask < uniform && bestErr > 0; mask = mask === 0 ? 1 : mask + 2) {
    const sum = [
      [0, 0, 0, 0],
      [0, 0, 0, 0],
    ]
    rgb.forEach(([r, g, b], i) => {
      const s = sum[(mask >> i) & 1]!
      s[0]! += r!
      s[1]! += g!
      s[2]! += b!
      s[3]!++
    })
    const mean = sum.map(([r, g, b, k]) => (k ? [r! / k!, g! / k!, b! / k!] : [0, 0, 0]))
    let err = 0
    rgb.forEach((p, i) => {
      const m = mean[(mask >> i) & 1]!
      err += (p[0]! - m[0]!) ** 2 + (p[1]! - m[1]!) ** 2 + (p[2]! - m[2]!) ** 2
    })
    if (err < bestErr) {
      bestErr = err
      const [bg, fg] = mean.map(([r, g, b]) => (Math.round(r!) << 16) | (Math.round(g!) << 8) | Math.round(b!))
      best = mask === 0 ? { ch: ' ', fg: -1, bg: bg! } : { ch: sub === 2 ? QUADS[mask]! : sextant(mask), fg: fg!, bg: bg! }
    }
  }
  return best
}

/** The pixels of cell (x, y) of a picture `w` pixels wide, 2 x `sub` to a cell, in reading order. */
function pixelsOf(pic: number[], w: number, x: number, y: number, sub: Sub): number[] {
  const out: number[] = []
  for (let dy = 0; dy < sub; dy++) {
    const i = (sub * y + dy) * w + 2 * x
    out.push(pic[i]!, pic[i + 1]!)
  }
  return out
}

const cellOf = (pic: number[], w: number, x: number, y: number, sub: Sub) => block(pixelsOf(pic, w, x, y, sub), sub)

/** A cell made of quadrants, each a frame colour or -1: drawn in the first colour found. */
function quads(q: [number, number, number, number]): Cell {
  const fg = q.find(c => c >= 0)
  if (fg === undefined) return BLANK
  const mask = q.reduce((m, c, i) => (c === fg ? m | (1 << i) : m), 0)
  return { ch: QUADS[mask]!, fg, bg: -1 }
}

/** Rows `from` to `to` of the board's cells: tiles with gaps, or the whole picture. */
function boardCells(g: Puzzle, l: Layout, from: number, to: number): Cell[][] {
  const pw = 2 * l.n * l.tw
  const pic = picture(g.art, pw, l.sub * l.n * l.th)
  const whole = g.peek || isSolved(g)
  const frame = (r: number, c: number) => {
    if (r < 0 || c < 0 || r >= l.n || c >= l.n) return -1
    const p = r * l.n + c
    return p === g.pick ? PICKED : p === g.cur ? CURSOR : -1
  }
  const rows: Cell[][] = []
  for (let by = from; by < to; by++) {
    const row: Cell[] = []
    for (let bx = 0; bx < l.width; bx++) {
      if (whole) {
        // The picture in one piece, centred in the board's box.
        const ox = bx - Math.floor((l.width - l.n * l.tw) / 2)
        const oy = by - Math.floor((l.height - l.n * l.th) / 2)
        row.push(ox >= 0 && ox < l.n * l.tw && oy >= 0 && oy < l.n * l.th ? cellOf(pic, pw, ox, oy, l.sub) : BLANK)
        continue
      }
      const slot = l.th + l.gap
      const gx = bx % (l.tw + 1) === 0
      const gy = l.gap > 0 && by % slot === 0
      const c = Math.floor(bx / (l.tw + 1))
      const r = Math.floor(by / slot)
      if (gx && gy) {
        row.push(quads([frame(r - 1, c - 1), frame(r - 1, c), frame(r, c - 1), frame(r, c)]))
      } else if (gx) {
        const left = frame(r, c - 1)
        const right = frame(r, c)
        if (left >= 0) row.push({ ch: '▌', fg: left, bg: right })
        else row.push(right >= 0 ? { ch: '▐', fg: right, bg: -1 } : BLANK)
      } else if (gy) {
        const above = frame(r - 1, c)
        const below = frame(r, c)
        if (above >= 0) row.push({ ch: '▀', fg: above, bg: below })
        else row.push(below >= 0 ? { ch: '▄', fg: below, bg: -1 } : BLANK)
      } else {
        const piece = g.order[r * l.n + c]!
        const ly = by - r * slot - l.gap
        const x = (piece % l.n) * l.tw + (bx - c * (l.tw + 1) - 1)
        const y = Math.floor(piece / l.n) * l.th + ly
        if (l.gap === 0 && ly === 0) {
          // Without gap rows, a tile's top half-row is the gap: empty, or a frame's edge.
          const below = pixelsOf(pic, pw, x, y, l.sub).slice(2)
          const edge = frame(r - 1, c) >= 0 ? frame(r - 1, c) : frame(r, c)
          row.push({ ch: '▄', fg: meanOf(below), bg: edge })
        } else {
          row.push(cellOf(pic, pw, x, y, l.sub))
        }
      }
    }
    rows.push(row)
  }
  return rows
}

/** Row `y` of the picture drawn `t` columns wide beside the board. */
function thumbRow(g: Puzzle, t: number, y: number, sub: Sub): Cell[] {
  const pic = picture(g.art, 2 * t, (sub * t) / 2)
  return Array.from({ length: t }, (_, x) => cellOf(pic, 2 * t, x, y, sub))
}

const hex = (c: number) => '#' + c.toString(16).padStart(6, '0')

/** One row of cells as few Text spans as their colours allow. */
function spans(cells: Cell[], Text: ClientElements['Text']): RenderElement[] {
  const out: RenderElement[] = []
  let run = ''
  let fg = -1
  let bg = -1
  const flush = () => {
    if (!run) return
    const style: { color?: string; backgroundColor?: string } = {}
    if (fg >= 0) style.color = hex(fg)
    if (bg >= 0) style.backgroundColor = hex(bg)
    out.push(<Text {...style}>{run}</Text>)
    run = ''
  }
  for (const cell of cells) {
    // A space shows only its background, so it joins a run of any foreground.
    const fits = cell.bg === bg && (cell.ch === ' ' || fg < 0 || cell.fg === fg)
    if (!fits) {
      flush()
      fg = -1
    }
    bg = cell.bg
    if (cell.ch !== ' ' && fg < 0) fg = cell.fg
    run += cell.ch
  }
  flush()
  return out
}

export type DrawOptions = {
  busy: boolean
  /** Pictures made whole so far, across sessions. */
  solved: number
  help: string
}

const pad = (s: string, n: number) => (s.length >= n ? s.slice(0, n) : s + ' '.repeat(n - s.length))

/** How many rows the whole drawing takes: header, board and footer. */
export const rowCount = (l: Layout) => l.top + l.height + l.footer

/**
 * Rows `from` to `to` (exclusive) of the drawing, one Text each. A board
 * band draws its slice of them, so no one `Client` holds every pixel.
 */
export function drawRows(
  g: Puzzle,
  Text: ClientElements['Text'],
  l: Layout,
  o: DrawOptions,
  from = 0,
  to = rowCount(l),
): RenderElement[] {
  const solved = isSolved(g)
  const boardFrom = Math.max(from, l.top) - l.top
  const boardTo = Math.min(to, l.top + l.height) - l.top
  const board = boardTo > boardFrom ? boardCells(g, l, boardFrom, boardTo) : []
  // The picture beside the board, while the board does not show it whole.
  const showThumb = l.thumb > 0 && !(g.peek || solved)
  const out: RenderElement[] = []

  for (let y = from; y < to; y++) {
    if (y < l.top) {
      const title = ` ▌${artOf(g.art).title}`
      const stats = solved
        ? `Whole · ${g.moves} moves `
        : `${placed(g)}/${g.order.length} in place · ${g.moves} moves `
      const header = title + ' '.repeat(Math.max(1, l.columns - title.length - stats.length)) + stats
      out.push(<Text bold color="#e8e4dc" wrap="truncate">{pad(header, l.columns)}</Text>)
    } else if (y < l.top + l.height) {
      const by = y - l.top
      const row: Cell[] = [...Array.from({ length: l.left }, () => BLANK), ...board[by - boardFrom]!]
      const t = by - 1
      if (showThumb && t >= 0 && t < l.thumb / 2) {
        row.push(...Array.from({ length: THUMB_GAP }, () => BLANK), ...thumbRow(g, l.thumb, t, l.sub))
      }
      out.push(<Text wrap="truncate">{spans(row, Text)}</Text>)
    } else {
      const f = y - l.top - l.height
      if (f === 0) {
        out.push(<Text color={solved ? '#8fd694' : '#e8e4dc'} wrap="truncate">{' ' + g.msg}</Text>)
      } else if (f === 1) {
        const agents = o.busy ? ' ● Your agents are at work. Puzzle while you wait.' : ' ○ Your agents are idle.'
        const count = o.solved > 0 ? `  Pictures made whole: ${o.solved}` : ''
        out.push(<Text color={o.busy ? '#f4d35e' : '#8fd694'} wrap="truncate">{agents + count}</Text>)
      } else {
        out.push(<Text dimColor wrap="truncate">{' ' + o.help}</Text>)
      }
    }
  }
  return out
}

export function drawBoard(g: Puzzle, els: Pick<ClientElements, 'Box' | 'Text'>, l: Layout, o: DrawOptions): RenderElement {
  const { Box, Text } = els
  return <Box flexDirection="column">{drawRows(g, Text, l, o)}</Box>
}

