{
  "name": "puzzle",
  "version": "0.1.0",
  "description": "Tile puzzles of Obol's shades art while your agents work: swap the pieces until the picture is whole.",
  "author": {
    "name": "Magnus Widerberg"
  },
  "types": "./types/index.d.ts"
}

files.types/index.d.ts:
/** A puzzle in progress: the picture is cut into `n` x `n` tiles and shuffled. */
export type Puzzle = {
  v: 1
  /** Counts every change, so a board band can tell a newer puzzle from its own. */
  rev: number
  seed: number
  /** The picture's id in `ART`. */
  art: string
  /** Tiles per side. */
  n: number
  /** The piece shown at each position; the picture is whole when `order[p] === p`. */
  order: number[]
  /** The position under the cursor. */
  cur: number
  /** The picked position waiting for a swap; -1 for none. */
  pick: number
  moves: number
  /** True while the whole picture is shown in place of the tiles. */
  peek: boolean
  /** True after `n` on an unfinished puzzle: a second `n` moves on, anything else stays. */
  asking?: boolean
  msg: string
}

declare module 'claude-code' {
  interface PluginState {
    puzzle: {
      /** True while a turn runs: the agents are working. */
      busy: boolean
      /** The puzzle in play, which every board band and the button board draw. */
      game: Puzzle | null
    }
  }
}
